#!/usr/bin/env bash
set -euo pipefail
script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"; compose_file="$script_dir/compose.yml"; die(){ echo "owner-marketing check: $*" >&2; exit 1; }
cd "$script_dir/../../../.."; source_sha="$(git rev-parse HEAD)"; export MAUTIC_SOURCE_SHA="$source_sha"; [[ -z "$(git status --porcelain)" ]] || die dirty-or-untracked-source; git ls-files --error-unmatch apps/window/infra/owner_marketing/compose.yml apps/window/infra/owner_marketing/deploy.sh apps/window/infra/owner_marketing/check.sh >/dev/null || die untracked-source; cd "$script_dir"
secret_dir=/srv/frank/secrets/owner-marketing; env_file="$secret_dir/owner-marketing.env"; [[ -f "$env_file" && ! -L "$env_file" ]] || die missing-secret; [[ "$(stat -c '%U:%a' "$secret_dir")" == root:700 && "$(stat -c '%U:%a' "$env_file")" == root:600 ]] || die unsafe-secret-permissions
cfg="$(docker compose --project-name frank-owner-marketing --env-file "$env_file" -f "$compose_file" config --format json)" || die invalid-compose; printf '%s' "$cfg" | python3 -c 'import json,sys; c=json.load(sys.stdin)["services"]; assert c["mautic"]["ports"][0]["host_ip"]=="127.0.0.1"; assert c["mautic"]["environment"]["MAUTIC_RUN_CRON_JOBS"]=="false"; assert c["mautic"]["environment"]["MAUTIC_MAILER_TRANSPORT"]=="smtp" and c["mautic"]["environment"]["MAUTIC_MAILER_HOST"]=="mail-sink.invalid"; assert set(c["db"]["networks"])=={"owner_marketing_private"} and set(c["mautic"]["networks"])=={"owner_marketing_private"}' || die policy-failed
docker inspect frank-owner-marketing frank-owner-marketing-db >/dev/null 2>&1 || die missing-containers; [[ "$(docker inspect --format '{{index .Config.Labels "org.frank.source-sha"}}' frank-owner-marketing)" == "$source_sha" ]] || die source-sha-mismatch; [[ "$(docker inspect --format '{{index .Config.Labels "org.frank.image-digest"}}' frank-owner-marketing)" == "sha256:39e967af9f154d50d1a7cbc12e6cfd5a847939c8abdcace98ab20e30570bdfda" ]] || die image-digest-mismatch; [[ "$(docker inspect --format '{{.State.Health.Status}}' frank-owner-marketing)" == healthy ]] || die mautic-unhealthy; [[ "$(docker inspect --format '{{.State.Health.Status}}' frank-owner-marketing-db)" == healthy ]] || die db-unhealthy
curl --fail --silent --show-error --connect-timeout 3 "http://127.0.0.1:${MAUTIC_HOST_PORT:-18106}/" >/dev/null || die http-failed; echo "healthy: private loopback Mautic 7.2, MySQL 8.4, cron disabled, null mail transport, internal egress network"
